<script setup lang="ts">
import { computed, ref } from 'vue';
import { Send, RotateCw, ExternalLink } from '@lucide/vue';
import type { AutomationTask } from '../../../shared/automation';
import { api, platform, message } from '../api';
import { notify } from '../lib/notifications';
const props=defineProps<{task:AutomationTask}>();const emit=defineEmits<{changed:[]}>();
const busy=ref(false),error=ref(''),targetId=ref(''),targetUrl=ref('');
const enabled=computed(()=>platform.settings?.environments.find(e=>e.id===props.task.environmentId)?.delivery?.enabled);
const names={queued:'等待交付',running:'迁移中',uncertain:'迁移结果待核查',verifying:'交付核验中',completed:'交付核验完成',failed:'交付未完成'};
async function action(suffix='',body?:unknown){busy.value=true;error.value='';try{await api(`/automation/tasks/${props.task.id}/delivery${suffix}`,{method:'POST',...(body?{body:JSON.stringify(body)}:{})});notify.success(suffix==='/receipt'?'回执已保存，已排队核验':suffix==='/cancel'?'已请求停止交付':suffix==='/confirm-stopped'?'已确认停止，可恢复核验':'已排队交付核验');emit('changed');}catch(e){error.value=message(e);}finally{busy.value=false;}}
</script>
<template><section v-if="task.kind==='evaluation'&&(enabled||task.delivery)" class="panel settings-panel delivery-panel"><div class="section-heading"><h2>跨环境交付</h2><button v-if="!task.delivery&&task.status==='completed'&&task.report" class="button secondary small" :disabled="busy" @click="action()"><Send :size="15"/>迁移并核验</button></div><template v-if="task.delivery"><div class="inline-actions"><strong>{{names[task.delivery.status]}}</strong><a v-if="task.delivery.target" class="text-action" :href="task.delivery.target.siteUrl" target="_blank" rel="noopener noreferrer">打开目标站<ExternalLink :size="14"/></a><button v-if="task.delivery.status==='failed'&&!task.delivery.target&&!task.delivery.attemptedAt" class="button secondary small" :disabled="busy" @click="action('/retry')">重试迁移准备</button><button v-if="task.delivery.stopped!==false&&task.delivery.target&&['failed','completed'].includes(task.delivery.status)" class="button secondary small" :disabled="busy" @click="action('/verify')"><RotateCw :size="14"/>恢复 / 重新核验</button><button v-if="['queued','running','verifying'].includes(task.delivery.status)" class="button secondary small" :disabled="busy" @click="action('/cancel')">停止交付</button></div><button v-if="task.delivery.stopped===false&&['failed','uncertain'].includes(task.delivery.status)" class="button secondary small" :disabled="busy" @click="action('/confirm-stopped')">已检查原浏览器，确认交付执行停止</button><p v-if="task.delivery.error" class="alert info">{{task.delivery.error}}</p><div v-if="!task.delivery.target&&['uncertain','failed'].includes(task.delivery.status)" class="delivery-receipt"><p>在目标环境或迁移服务核查实际结果后，补录已创建站点的回执；系统会确认目标身份并继续核验。</p><div class="form-grid"><label class="field"><span>目标 Site ID</span><input v-model="targetId" class="input"/></label><label class="field"><span>目标站 URL</span><input v-model="targetUrl" class="input" type="url"/></label></div><button class="button secondary small" :disabled="busy||!targetId||!targetUrl" @click="action('/receipt',{siteId:targetId,siteUrl:targetUrl})">保存回执并核验</button></div><div v-if="task.delivery.verification"><p>{{task.delivery.verification.summary}}</p><div class="coverage-grid"><div><h3>已验证</h3><ul><li v-for="text in task.delivery.verification.verified" :key="text">{{text}}</li></ul></div><div><h3>未验证 / 未通过</h3><ul><li v-for="text in task.delivery.verification.unverified" :key="text">{{text}}</li></ul></div></div><div class="evidence-grid"><a v-for="file in task.delivery.artifacts?.filter(f=>f.type==='image/png')" :key="file.id" :href="`/api/v1/automation/reports/${task.id}/delivery/artifacts/${file.name}`" target="_blank"><img :src="`/api/v1/automation/reports/${task.id}/delivery/artifacts/${file.name}`" loading="lazy" :alt="`交付核验证据 ${file.name}`"/></a></div></div><details v-if="task.delivery.checks.length"><summary>访问检查</summary><p v-for="check in task.delivery.checks" :key="check.url">{{check.ok?'通过':'未通过'}} · {{check.url}} · {{check.detail}}</p></details></template><p v-else class="text-muted">完成源环境评测后可发起交付；迁移及核验独立记录，保留源站报告。</p><p v-if="error" class="alert error">{{error}}</p></section></template>

<style scoped>
.delivery-panel{display:flex;flex-direction:column;gap:16px}.delivery-panel .section-heading,.delivery-panel .inline-actions,.delivery-panel h2{margin:0}.delivery-panel .inline-actions{flex-wrap:wrap}.delivery-receipt{display:flex;flex-direction:column;gap:16px}
</style>
